452	// CapturePreTaskState captures current untracked files before a Task execution
453	// and saves them to a state file.
454	// Works correctly from any subdirectory within the repository.
455	func CapturePreTaskState(ctx context.Context, toolUseID string) error {
456		if toolUseID == "" {
457			return errors.New("tool_use_id is required")
458		}
459	
460		if err := validation.ValidateToolUseID(toolUseID); err != nil {
461			return fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
462		}
463	
464		// Get absolute path for tmp directory
465		tmpDirAbs := resolveTmpDir(ctx)
466	
467		// Create tmp directory if it doesn't exist
468		if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
469			return fmt.Errorf("failed to create tmp directory: %w", err)
470		}
471	
472		// Get list of untracked files (excluding .entire directory itself)
473		untrackedFiles, err := getUntrackedFilesForState(ctx)
474		if err != nil {
475			return fmt.Errorf("failed to get untracked files: %w", err)
476		}
477	
478		// Create state file using os.Root for traversal-resistant write
479		state := PreTaskState{
480			ToolUseID:      toolUseID,
481			Timestamp:      time.Now().UTC().Format(time.RFC3339),
482			UntrackedFiles: untrackedFiles,
483		}
484	
485		data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
486		if err != nil {
487			return fmt.Errorf("failed to marshal state: %w", err)
488		}
489	
490		fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
491		root, err := os.OpenRoot(tmpDirAbs)
492		if err != nil {
493			return fmt.Errorf("failed to open tmp directory root: %w", err)
494		}
495		defer root.Close()
496	
497		if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
498			return fmt.Errorf("failed to write state file: %w", err)
499		}
500	
501		logging.Debug(logging.WithComponent(ctx, "state"), "captured state before task",
502			slog.Int("untracked_files", len(untrackedFiles)))
503		return nil
504	}
